drop function public.midad_catalog(text,text,text,text,text,uuid,boolean,integer,integer);
create function public.midad_catalog(p_query text default '',p_genre text default '',p_status text default '',p_age text default '',p_sort text default 'recent',p_author uuid default null,p_profile_only boolean default false,p_limit integer default 24,p_offset integer default 0,p_novel uuid default null,p_saved boolean default false,p_following boolean default false) returns table(id uuid,title text,description text,cover_path text,author_id uuid,author_name text,author_username text,author_avatar text,genres text[],tags text[],status text,age_rating text,language text,warnings text[],chapter_count bigint,word_count bigint,rating_avg numeric,rating_count bigint,rank_score numeric,updated_at timestamptz,featured boolean) language sql stable security definer set search_path='' as $$
 with pub as(select b.project_id,count(distinct c.id) as chapters,coalesce(sum((select coalesce(sum(case when trim(s.plain_text)='' then 0 else cardinality(regexp_split_to_array(trim(s.plain_text),E'\\s+')) end),0) from public.midad_scenes s where s.chapter_id=c.id)),0) as words from public.midad_publications pp join public.midad_chapters c on c.id=pp.chapter_id and c.draft_id is null join public.midad_books b on b.id=c.book_id group by b.project_id),ratings as(select r.project_id,round(avg(r.score),2) as average,count(*) as n,(sum(r.score)+17.5)/(count(*)+5) as confidence from public.midad_ratings r group by r.project_id),data as(
 select p.id,p.title,p.description,p.cover_path,p.user_id as author_id,coalesce(pr.display_name,'كاتب في مِداد') as author_name,pr.username as author_username,case when pr.is_public then pr.avatar_path end as author_avatar,array(select g.genre_code from public.midad_project_genres g where g.project_id=p.id order by g.genre_code) as genres,array(select t.tag from public.midad_novel_tags t where t.project_id=p.id order by t.tag) as tags,coalesce(m.status,'ongoing') as status,coalesce(m.age_rating,'all') as age_rating,coalesce(m.language,'ar') as language,coalesce(m.warnings,'{}') as warnings,coalesce(pub.chapters,0) as chapter_count,coalesce(pub.words,0)::bigint as word_count,coalesce(r.average,0) as rating_avg,coalesce(r.n,0) as rating_count,coalesce(r.confidence,0) as rank_score,p.updated_at,coalesce(s.featured,false) as featured,coalesce(s.position,0) as shelf_position,s.project_id is not null and pr.is_public as in_profile
 from public.midad_projects p left join public.midad_profiles pr on pr.user_id=p.user_id left join public.midad_showcase s on s.project_id=p.id left join public.midad_novel_metadata m on m.project_id=p.id left join pub on pub.project_id=p.id left join ratings r on r.project_id=p.id where midad_private.public_novel(p.id))
 select d.id,d.title,d.description,d.cover_path,d.author_id,d.author_name,d.author_username,d.author_avatar,d.genres,d.tags,d.status,d.age_rating,d.language,d.warnings,d.chapter_count,d.word_count,d.rating_avg,d.rating_count,d.rank_score,d.updated_at,d.featured from data d where (p_novel is null or d.id=p_novel) and (not p_saved or exists(select 1 from public.midad_reading_list rl where rl.project_id=d.id and rl.user_id=auth.uid())) and (not p_following or exists(select 1 from public.midad_follows f where f.author_id=d.author_id and f.follower_id=auth.uid())) and (p_author is null or d.author_id=p_author) and (not p_profile_only or d.in_profile) and (p_query='' or concat_ws(' ',d.title,d.description,d.author_name,d.author_username,array_to_string(d.tags,' ')) ilike '%'||left(p_query,150)||'%') and(p_genre='' or p_genre=any(d.genres)) and(p_status='' or d.status=p_status) and(p_age='' or d.age_rating=p_age)
 order by case when p_sort='rating' then (d.rating_count>0)::integer end desc nulls last,case when p_sort='rating' then d.rank_score end desc nulls last,case when p_sort='popular' then d.rating_count end desc nulls last,case when p_sort='profile' then d.featured::integer end desc nulls last,case when p_sort='profile' then d.shelf_position end asc nulls last,d.updated_at desc,d.id limit least(greatest(p_limit,1),100) offset least(greatest(p_offset,0),10000)
 $$;
revoke all on function public.midad_catalog(text,text,text,text,text,uuid,boolean,integer,integer,uuid,boolean,boolean) from public;grant execute on function public.midad_catalog(text,text,text,text,text,uuid,boolean,integer,integer,uuid,boolean,boolean) to anon,authenticated;
